"""One-shot exact publication check. No commit/push or numerical execution."""
from pathlib import Path
import hashlib,json,subprocess
R=Path(__file__).resolve().parents[4];D=Path(__file__).resolve().parent
NAMES = ['diagnostics/simplex-core-architecture/DIRECT-LU-ADMISSION.md', 'diagnostics/simplex-core-architecture/STATUS.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/STATUS.md.before-admission', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/admission-reviewed.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/admission.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/audit.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/audit_reviewed.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/closure.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/closure.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/config.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/configure.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/continuation.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/control.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/control_reviewed.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/driver.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/evidence_reviewed.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/focused/lifecycle.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/focused/markowitz-fill.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/focused/markowitz-sparse.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/focused/markowitz-triangular.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/focused/prepared.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/focused/stability.jl', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/freeze-reviewed.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/freeze.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/guard.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/host.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/initial/control.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/launch-reviewed.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/launch.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/offline-tests-2.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/offline-tests.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/offline-tests.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/preparation-failure.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/preparation-pins-reviewed.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/preparation-pins.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/preparation-review-final.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/preparation-review-final.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/preparation-review.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/preparation-review.md', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/prepare.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/publication.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/publication.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/required-reviewed.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/required.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/review-fix-tests.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/review-fix-tests.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/roadmap.md.before-admission', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/seal-reviewed.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/seal.py', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/staging.json', 'diagnostics/simplex-core-architecture/results/DIRECT-LU-ADMISSION/supervisor.py', 'docs/superpowers/plans/2026-10-11-simplex-core-architecture.md']
def git(*args):return subprocess.check_output(['git',*args],cwd=R,text=True).strip()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
closure=json.loads((D/'closure.json').read_text())
if not closure['all_passed'] or not all(sha(R/n)==h for n,h in closure['sha256'].items()):raise SystemExit('Closure failed or bindings changed')
if git('diff','--cached','--name-only'):raise SystemExit('Index must start empty')
selfname=str((D/'publication.json').relative_to(R));other=[n for n in NAMES if n!=selfname]
if any(not (R/n).is_file() for n in other):raise SystemExit('Missing declared file')
subprocess.run(['git','add','--',*other],cwd=R,check=True)
if sorted(git('diff','--cached','--name-only').splitlines())!=sorted(other):raise SystemExit('Initial exact staged set mismatch')
blobs={n:git('rev-parse',':'+n) for n in other}
if any(git('hash-object',n)!=h for n,h in blobs.items()):raise SystemExit('Staged/working mismatch')
def check_whitespace():
    expected={str(D.relative_to(R)/'focused'/name)+':'+str(line)+': new blank line at EOF.' for name,line in [('stability.jl',21),('markowitz-triangular.jl',36),('markowitz-sparse.jl',52),('markowitz-fill.jl',25)]}
    result=subprocess.run(['git','diff','--cached','--check'],cwd=R,text=True,capture_output=True)
    if result.stderr or set(result.stdout.splitlines())!=expected or result.returncode!=2:raise SystemExit('Unexpected staged whitespace diagnostics: '+repr(result))
    # These four warnings preserve exact original source slices, already checked by closure.
    return result.stdout.splitlines()
whitespace=check_whitespace()
with (D/'publication.json').open('x') as f:json.dump({'all_passed':True,'scope':'OFFLINE short-run admission preparation; no Julia execution or production promotion','exact_names':NAMES,'staged_blobs_excluding_self':blobs,'sha256':{n:sha(R/n) for n in other},'preserved_exact_source_whitespace':whitespace,'self_binding':'Included in exact staged set, bound by committed tree; postcommit verifies actual self blob too.'},f,indent=2);f.write('\n')
subprocess.run(['git','add','--',selfname],cwd=R,check=True)
if sorted(git('diff','--cached','--name-only').splitlines())!=NAMES:raise SystemExit('Final exact staged set mismatch')
check_whitespace()
print(json.dumps({'all_passed':True,'exact_staged_names':len(NAMES),'bound_other_blobs':len(blobs)}))
